2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Maps an owner's {@link MembershipPoints} score to a numeric membership level: level 1
9	 * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more points.
10	 *
11	 * <p>An owner may carry a household level ceiling ({@link Owner#getMembershipLevelCap()});
12	 * when present it caps the effective level, so a new owner never outranks the highest of
13	 * their existing household members by more than one.
14	 */
15	public final class MembershipLevel {
16	
17	    /** Lowest level attainable. */
18	    public static final int MIN = 1;
19	
20	    /** Highest level attainable. */
21	    public static final int MAX = 4;
22	
23	    private MembershipLevel() {
24	    }
25	
26	    /** The membership level for the given owner as of today. */
27	    public static int of(Owner owner) {
28	        return of(owner, LocalDate.now());
29	    }
30	
31	    /** The membership level for the given owner, with tenure measured as of {@code asOf}.
32	     *  Limited by the owner's stored household level ceiling when one is set. */
33	    public static int of(Owner owner, LocalDate asOf) {
34	        return capped(forPoints(MembershipPoints.of(owner, asOf)), owner.getMembershipLevelCap());
35	    }
36	
37	    /** Apply a household level ceiling: {@code cap} (when non-null) limits {@code level}. */
38	    private static int capped(int level, Integer cap) {
39	        return cap == null ? level : Math.min(level, cap);
40	    }
41	
42	    /** The membership level for a given membership points score. */
43	    public static int forPoints(int points) {
44	        if (points >= 6) {
45	            return 4;
46	        }
47	        if (points >= 4) {
48	            return 3;
49	        }
50	        if (points >= 2) {
51	            return 2;
52	        }
53	        return 1;
54	    }
55	}
